<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Holder\TemplateAssetTemplateAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TemplateAssetTemplateAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TemplateAssetTemplateAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getTemplate returns null on a freshly created holder.
     */
    public function testTemplateNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTemplateAssetTemplateAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isTemplateAssigned());
        $this->assertNull($holder->getTemplate());
    }
}
class ImplWithTemplateAssetTemplateAttributeHolderUnitTest
{
    use TemplateAssetTemplateAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedTemplateRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultTemplate();
    }
}
